/**
 * Look up an international rate.
 * @param {string} svcKey  - e.g. 'wwe_exp', 'std_ca'
 * @param {string} ct      - container type: 'Ltr' | 'Pak' | 'Doc' | 'Pkg'
 * @param {number} zone    - UPS zone number
 * @param {number} weight  - billable weight in lbs
 * @returns {number|null}
 */
export function lookupIntlRate(svcKey, ct, zone, weight) {
  const table = INTL_RATES[svcKey]?.[ct];
  if (!table) return null;
  const zs = String(zone);
  const w = Math.ceil(weight);

  // Over-max weight: use per-lb rate on top of max weight rate
  if (table['151'] && w > 150) {
    const base = table['150'];
    const perLb = table['151'];
    if (!base?.[zs] || !perLb?.[zs]) return null;
    return +(base[zs] + (w - 150) * perLb[zs]).toFixed(2);
  }

  if (table[w]?.[zs] !== undefined) return table[w][zs];

  // Interpolate between weight breaks
  const weights = Object.keys(table).map(Number).filter(n => n <= 150).sort((a, b) => a - b);
  for (let i = weights.length - 1; i >= 0; i--) {
    if (weights[i] < w && table[weights[i]]?.[zs] !== undefined) {
      const lo = weights[i], lr = table[lo][zs];
      const hi = weights.find(x => x > lo && table[x]?.[zs] !== undefined);
      if (!hi) return lr;
      return +(lr + ((w - lo) / (hi - lo)) * (table[hi][zs] - lr)).toFixed(2);
    }
  }
  return null;
}
